    const fullName = user.name || user.fullName || (username.toLowerCase() === 'darrell' ? 'Darrell Laliberte' : username);
    const now = new Date();
    const set = (id, value) => { const element = document.getElementById(id); if (element) element.value = value; };
    set('transaction-session-user', username);
    set('transaction-session-name', fullName);
