  async function fetchUserProfile(username) {
    if (!window.sbFetch) return null;
    const res = await window.sbFetch('profiles?select=username,email,role,status,mfa&username=eq.' + encodeURIComponent(username));
    if (!res.ok) return null;
    const rows = await res.json();
    return rows[0] || null;
  }
  async function allDbUsers() {
    if (!window.sbFetch) return [];
    try { const s=JSON.parse(sessionStorage.getItem('registryPosSession')||'null'); if(!s?.username) return []; } catch(_) { return []; }
    try {
      const res = await window.sbFetch('profiles?select=username,role,status,mfa&order=username.asc');
      if (!res.ok) return [];
      return await res.json();
    } catch (_) { return []; }
  }
  async function renderUsers() {
    const body = document.getElementById('user-list-body');
    const users = await allDbUsers();
    if (body) body.innerHTML = users.map(user => `<tr><td>${escapeHtml(user.username)}</td><td>${escapeHtml(user.role)}</td><td>${escapeHtml(user.status)}</td><td>Available</td><td>${escapeHtml(user.mfa || 'Optional')}</td></tr>`).join('');
    const selector = document.getElementById('selected-user');
    if (selector) {
      const current = selector.value;
      selector.innerHTML = '<option value="">Select a user</option>' + users.map(user => `<option value="${escapeHtml(user.username)}">${escapeHtml(user.username)}</option>`).join('');
      selector.value = current;
    }
  }
  async function tryLogin() {
    const username = document.getElementById('login-user').value.trim();
    const password = document.getElementById('login-password').value;
    const status = document.getElementById('login-status');
    if (!username || !password) { alert('Enter a user name and password.'); return; }
    if (!window.SB_URL || !window.SB_KEY) { alert('Database connection is not ready yet. Please try again in a moment.'); return; }
    try {
      const profile = await fetchUserProfile(username);
      const authEmail = profile?.email || username;
      const authRes = await fetch(window.SB_URL + '/auth/v1/token?grant_type=password', {
        method: 'POST',
        headers: { 'apikey': window.SB_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: authEmail, password })
      });
      const authData = await authRes.json();
      if (!authRes.ok || !authData.access_token) {
        alert('Invalid user name or password.');
        return;
      }
      if (profile && profile.status && profile.status !== 'Active') {
        alert('This account is not active. Contact an administrator.');
        return;
      }
      sessionStorage.setItem('registryPosSession', JSON.stringify({ username: profile?.username || username, role: profile?.role || 'User', accessToken: authData.access_token, loggedInAt: Date.now() }));
      const welcomeName = document.getElementById('switchboard-user');
      if (welcomeName) welcomeName.textContent = profile?.username || username;
      window.currentPrototypeUser = { username: profile?.username || username, role: profile?.role || 'User' };
      updateTransactionSessionFields();
      showPage('switchboard-page');
      renderUsers(); // load user list immediately after login
      window.sbLoadInitialData?.();
    } catch (error) {
      console.error(error);
      alert('Sign-in failed: ' + (error.message || 'Unable to reach the database.'));
    }
  }
  if (loginBtn) {
    loginBtn.addEventListener('click', tryLogin);
  }
  document.getElementById('login-password').addEventListener('keydown', event => {
    if (event.key === 'Enter') tryLogin();
  });
