  function currentTenderRows(){return [...document.querySelectorAll('.payment-tender-row')].map(r=>{const input=r.querySelector('input');const amount=money(input?.value);if(input)input.value=formatMoney(amount);return {method:r.querySelector('select')?.value||'Acct',amount};});}
  function renderTenderRows(tenders){const box=document.getElementById('payment-tender-lines');if(!box)return;const list=tenders?.length?tenders:[{method:'Acct',amount:0}];box.replaceChildren();list.forEach((t,index)=>{const row=document.createElement('div');row.className='payment-tender-row';const select=document.createElement('select');select.setAttribute('aria-label','Payment method');tenderMethods.forEach(method=>{const option=document.createElement('option');option.value=method;option.textContent=method;option.selected=method===t.method;select.appendChild(option);});const amount=document.createElement('input');amount.setAttribute('aria-label','Payment amount');amount.value=formatMoney(t.amount);const remove=document.createElement('button');remove.className='btn exit payment-tender-remove';remove.type='button';remove.setAttribute('aria-label','Remove payment');remove.textContent='×';remove.disabled=list.length===1;select.addEventListener('input',saveTenders);amount.addEventListener('input',saveTenders);remove.addEventListener('click',()=>{row.remove();saveTenders();});row.append(select,amount,remove);box.appendChild(row);});}
  function saveTenders(){const id=document.querySelector('.transaction-shell')?.dataset.transaction||'F120',tenders=currentTenderRows();transactionPayments[id]=transactionPayments[id]||{};transactionPayments[id].tenders=tenders;transactionPayments[id].paidBy=tenders[0]?.method||'Acct';transactionPayments[id].amount=tenders.reduce((sum,t)=>sum+t.amount,0);refreshTransactionTotals();window.sbPersistTransaction?.(id);}
