    document.getElementById('transaction-subtotal').value=formatMoney(subtotal);document.getElementById('transaction-total').value=formatMoney(total);document.getElementById('transaction-total-paid').value=formatMoney(paid);document.getElementById('transaction-change-due').value=formatMoney(Math.max(0,paid-total));
    const selected=document.querySelector('.transaction-row.selected');if(selected){selected.children[7].textContent=formatMoney(total);selected.children[8].textContent=currentTenderRows().map(t=>t.method).join(' + ');selected.children[9].textContent=formatMoney(paid);}
