  function sortTransactions(mode) {
    const body = document.querySelector('.transaction-list tbody');
    const rows = [...body.querySelectorAll('.transaction-row')];
    rows.sort((a, b) => {
      const aText = a.querySelector('.transaction-client-picker')?.value.trim() || a.children[3].textContent.trim();
      const bText = b.querySelector('.transaction-client-picker')?.value.trim() || b.children[3].textContent.trim();
      const aName = aText.replace(/^\d+\s*-\s*/, ''), bName = bText.replace(/^\d+\s*-\s*/, '');
      return mode === 'name' ? aName.localeCompare(bName, undefined, {numeric:true}) : aText.localeCompare(bText, undefined, {numeric:true});
    });
    rows.forEach(row => body.appendChild(row));
    updateTransactionListHeight();
  }

