  function updateTransactionLineTotal(row) {
    const value = label => parseFloat((row.querySelector('[aria-label="' + label + '"]')?.value || '').replace(/[^0-9.-]/g, '')) || 0;
    const qty = value('Quantity');
    const governmentCharge = value('Government charge');
    const serviceCharge = value('Service charge');
    const gsdEligible = row.querySelector('.gsd-line-check')?.checked;
    const gstField = row.querySelector('[aria-label="GST"]');
    const baseAmount = governmentCharge + serviceCharge;
    const gst = row.querySelector('.gst-line-check').checked ? baseAmount * 0.05 : 0;
    gstField.value = '$' + gst.toFixed(2);
    row.querySelector('.line-total-amount').textContent = '$' + (qty * (baseAmount + gst)).toFixed(2);
    const tag = row.querySelector('.on-account-tag');
    const payGovNow = row.querySelector('.pay-gov-now-check')?.checked;
    const parts = [];
    if (gsdEligible) parts.push('GSD tracked');
    if (governmentCharge) parts.push(payGovNow ? 'Govt paid today' : 'Govt payable later');
    if (tag) tag.textContent = parts.join(' • ');
    if (typeof refreshTransactionTotals === 'function') refreshTransactionTotals();
  }
