  const addUserBtn = document.getElementById('add-user-btn');
  if (addUserBtn) {
    addUserBtn.addEventListener('click', async () => {
      const username = document.getElementById('new-user-name').value.trim();
      const password = document.getElementById('new-user-password').value;
      const role = document.getElementById('new-user-role').value;
      const status = document.getElementById('new-user-status').value;
      const message = document.getElementById('user-maintenance-message');
      if (!username || password.length < 8) {
        message.textContent = 'Enter a user name and a temporary password of at least 8 characters.';
        return;
      }
      if (!/^[a-zA-Z0-9._-]+$/.test(username)) {
        message.textContent = 'User names may use letters, numbers, periods, hyphens, and underscores only.';
        return;
      }
      const existing = await fetchUserProfile(username);
      if (existing) {
        message.textContent = 'That user name already exists.';
        return;
      }
      message.textContent = 'Creating user…';
      try {
        const authEmail = username.includes('@') ? username : username + '@registrypos.local';
        const signUpRes = await fetch(window.SB_URL + '/auth/v1/signup', {
          method: 'POST',
          headers: { 'apikey': window.SB_KEY, 'Content-Type': 'application/json' },
          body: JSON.stringify({ email: authEmail, password })
        });
        const signUpData = await signUpRes.json();
        if (!signUpRes.ok || !signUpData.user) {
          message.textContent = 'Could not create user: ' + (signUpData.msg || signUpData.error_description || 'Unknown error.');
          return;
        }
        await window.sbFetch('profiles', {
          method: 'POST',
          headers: { 'Prefer': 'return=minimal' },
          body: JSON.stringify({ id: signUpData.user.id, username, email: authEmail, role, status, mfa: role === 'Admin' ? 'Enabled' : 'Optional' })
        });
        window.sbLogAudit?.('User Created', '', 'user', username, role, '');
        await renderUsers();
        document.getElementById('new-user-name').value = '';
        document.getElementById('new-user-password').value = '';
        document.getElementById('new-user-role').value = 'Cashier';
        document.getElementById('new-user-status').value = 'Active';
        message.textContent = username + ' was added. They can now sign in with the temporary password.';
      } catch (error) {
        console.error(error);
        message.textContent = 'Could not create user: ' + (error.message || 'Unable to reach the database.');
      }
    });
  }
