  let editingCatalogKey = null;
  function getCatalog() {
    try {
      const saved = JSON.parse(localStorage.getItem(catalogKey) || 'null');
      return Array.isArray(saved) && saved.length ? saved : defaultCatalog;
    } catch { return defaultCatalog; }
  }
  function saveCatalog(catalog) { localStorage.setItem(catalogKey, JSON.stringify(catalog)); if (typeof populateServiceProductLists === 'function') populateServiceProductLists(); }
  function populateServiceProductLists() {
    const catalog = getCatalog();
    const list = document.getElementById('service-product-options');
    if (list) list.innerHTML = catalog.map(item => '<option value="' + escapeHtml(item.description) + '">' + escapeHtml(item.serviceKey) + '</option>').join('');
  }
  let lastPickedCatalogKey = null;
  function applyCatalogItemToLine(select) {
    const item = getCatalog().find(row => row.description === select.value);
    if (!item) return;
    const row = select.closest('tr');
    row.querySelector('[aria-label="Government charge"]').value = item.registryCharge || '$0.00';
    row.querySelector('[aria-label="Service charge"]').value = item.companyCharge || '$0.00';
    const priceCode = row.querySelector('[aria-label="Matched price code"]'); if (priceCode) priceCode.value = item.serviceKey || '';
    const gst = row.querySelector('.gst-line-check');
    gst.checked = /gst/i.test(item.gstRule || '') && !/no gst/i.test(item.gstRule || '');
    const gsdBox = row.querySelector('.gsd-line-check');
    if (gsdBox) { gsdBox.checked = !!item.gsdEligible; row.classList.toggle('gsd-line', gsdBox.checked); }
    const payGovNowBox = row.querySelector('.pay-gov-now-check');
    if (payGovNowBox) payGovNowBox.checked = !!item.payGovNowDefault;
    updateTransactionLineTotal(row);
    resizeTransactionLineInputs();
    lastPickedCatalogKey = item.serviceKey;
    highlightCatalogRow(item.serviceKey);
  }
  populateServiceProductLists();
  document.querySelectorAll('.service-product-select').forEach(input => {
    input.addEventListener('change', () => applyCatalogItemToLine(input));
    input.addEventListener('blur', () => applyCatalogItemToLine(input));
  });
  function escapeHtml(value) { return String(value || '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char])); }
  function clearCatalogEditor() {
    editingCatalogKey = null;
    ['catalog-service-key','catalog-pos-code','catalog-description','catalog-registry-charge','catalog-company-charge'].forEach(id => document.getElementById(id).value = '');
    document.getElementById('catalog-service-group').value = 'Corporate';
    document.getElementById('catalog-gst-rule').value = 'No GST';
    document.getElementById('catalog-gsd-eligible').value = 'no';
    document.getElementById('catalog-pay-gov-now').value = 'no';
    document.getElementById('save-catalog-line-btn').textContent = 'Save Catalog Line';
  }
  function editCatalogLine(key) {
    const item = getCatalog().find(row => row.serviceKey === key);
    if (!item) return;
    editingCatalogKey = key;
    document.getElementById('catalog-service-key').value = item.serviceKey;
    document.getElementById('catalog-pos-code').value = item.posCode;
    document.getElementById('catalog-description').value = item.description;
    document.getElementById('catalog-registry-charge').value = item.registryCharge;
    document.getElementById('catalog-company-charge').value = item.companyCharge;
    document.getElementById('catalog-service-group').value = item.serviceGroup || 'General';
    document.getElementById('catalog-gst-rule').value = item.gstRule || 'No GST';
    document.getElementById('catalog-gsd-eligible').value = item.gsdEligible ? 'yes' : 'no';
    document.getElementById('catalog-pay-gov-now').value = item.payGovNowDefault ? 'yes' : 'no';
    document.getElementById('save-catalog-line-btn').textContent = 'Update Catalog Line';
    document.getElementById('catalog-service-key').focus();
  }
  function renderCatalog() {
    const body = document.getElementById('price-list-body');
    if (!body) return;
    const catalog = getCatalog();
    body.innerHTML = catalog.map(item => `<tr data-catalog-key="${escapeHtml(item.serviceKey)}"><td>${escapeHtml(item.serviceKey)}</td><td>${escapeHtml(item.description)}</td><td>${escapeHtml(item.registryCharge)}</td><td>${escapeHtml(item.companyCharge)}</td><td>${escapeHtml(item.posCode)}</td><td><span class="pos-match-tag pending">Awaiting live POS match</span></td><td><button class="btn" data-edit-catalog="${escapeHtml(item.serviceKey)}">Edit</button></td></tr>`).join('');
    body.querySelectorAll('[data-edit-catalog]').forEach(button => button.addEventListener('click', () => editCatalogLine(button.dataset.editCatalog)));
    if (lastPickedCatalogKey) highlightCatalogRow(lastPickedCatalogKey);
  }
  function highlightCatalogRow(serviceKey) {
    const body = document.getElementById('price-list-body');
    if (!body) return;
    body.querySelectorAll('tr').forEach(row => row.classList.toggle('catalog-row-picked', row.dataset.catalogKey === serviceKey));
    const banner = document.getElementById('catalog-picked-banner');
    if (!banner) return;
    if (!serviceKey) { banner.style.display = 'none'; return; }
    const item = getCatalog().find(row => row.serviceKey === serviceKey);
    banner.style.display = 'flex';
    banner.innerHTML = item
      ? `<span>Loaded from Data Entry: <strong>${escapeHtml(item.description)}</strong> (${escapeHtml(item.serviceKey)}) — Govt Charge, Svc Charge, GST rule, GSD flag, and Pay Govt Now default were applied to the line.</span><span class="pos-match-tag pending">POS code auto-match pending live database connection</span>`
      : '';
  }
  function readFile(input, callback) {
    const file = input.files && input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = event => callback(event.target.result, file.name);
    reader.readAsText(file);
  }
  document.getElementById('save-catalog-line-btn')?.addEventListener('click', () => {
    const item = {
      serviceKey: document.getElementById('catalog-service-key').value.trim(),
      posCode: document.getElementById('catalog-pos-code').value.trim(),
      description: document.getElementById('catalog-description').value.trim(),
      registryCharge: document.getElementById('catalog-registry-charge').value.trim() || '$0.00',
      companyCharge: document.getElementById('catalog-company-charge').value.trim() || '$0.00',
      serviceGroup: document.getElementById('catalog-service-group').value,
      gstRule: document.getElementById('catalog-gst-rule').value,
      gsdEligible: document.getElementById('catalog-gsd-eligible').value === 'yes',
      payGovNowDefault: document.getElementById('catalog-pay-gov-now').value === 'yes'
    };
    const message = document.getElementById('catalog-message');
    if (!item.serviceKey || !item.posCode || !item.description) { message.textContent = 'Service Key, POS Code, and Service Description are required.'; return; }
    const catalog = getCatalog();
    const existing = catalog.findIndex(row => row.serviceKey === editingCatalogKey || (!editingCatalogKey && row.serviceKey.toLowerCase() === item.serviceKey.toLowerCase()));
    if (existing >= 0) catalog[existing] = item; else catalog.push(item);
    saveCatalog(catalog); renderCatalog();
    message.textContent = item.serviceKey + (editingCatalogKey ? ' was updated.' : ' was added to the catalog.');
    clearCatalogEditor();
  });
  document.getElementById('clear-catalog-line-btn')?.addEventListener('click', clearCatalogEditor);
  document.getElementById('upload-price-list-btn')?.addEventListener('click', () => document.getElementById('price-list-file').click());
  document.getElementById('price-list-file')?.addEventListener('change', event => readFile(event.target, (csv, filename) => {
    const rows = parseCsv(csv);
    const catalog = rows.map(row => ({
      serviceKey: row.servicekey || row.poscode || row.code || '',
      description: row.servicedesc || row.description || row.servicedescription || '',
      registryCharge: row.registrycharge || row.govtcharge || row.governmentcharge || '$0.00',
      companyCharge: row.companycharge || row.servicecharge || row.svccharge || '$0.00',
      posCode: row.poscode || row.servicekey || row.code || ''
    })).filter(item => item.serviceKey);
    const message = document.getElementById('catalog-message');
    if (!catalog.length) { message.textContent = 'No usable rows were found. Include a Service Key or POS Code column in the CSV.'; return; }
    saveCatalog(catalog); renderCatalog();
    message.textContent = `${catalog.length} approved catalog item(s) were loaded from ${filename}.`;
    event.target.value = '';
  }));
  document.getElementById('import-match-pos-btn')?.addEventListener('click', () => document.getElementById('pos-codes-file').click());
  document.getElementById('pos-codes-file')?.addEventListener('change', event => readFile(event.target, (csv, filename) => {
    const rows = parseCsv(csv);
    const catalog = getCatalog();
    const approvedCodes = new Set(catalog.flatMap(item => [item.serviceKey, item.posCode]).map(value => value.toUpperCase()));
    const unmatched = rows.map(row => ({
      posCode: row.poscode || row.servicekey || row.code || '',
      machineReference: row.machineref || row.machinereference || row.machine || ''
    })).filter(item => item.posCode && !approvedCodes.has(item.posCode.toUpperCase()));
    localStorage.setItem(unmatchedKey, JSON.stringify(unmatched));
    document.getElementById('catalog-message').textContent = `${filename} was imported: ${rows.length - unmatched.length} matched, ${unmatched.length} unmatched.`;
    event.target.value = '';
  }));
  document.getElementById('review-unmatched-btn')?.addEventListener('click', () => {
    let unmatched = []; try { unmatched = JSON.parse(localStorage.getItem(unmatchedKey) || '[]'); } catch {}
    const panel = document.getElementById('unmatched-codes-panel');
    const body = document.getElementById('unmatched-codes-body');
    const count = document.getElementById('unmatched-count');
    panel.style.display = 'block';
    count.textContent = unmatched.length ? `${unmatched.length} code(s) need review` : 'No unmatched codes';
    body.innerHTML = unmatched.length ? unmatched.map(item => `<tr><td>${escapeHtml(item.posCode)}</td><td>${escapeHtml(item.machineReference || 'Not supplied')}</td><td>Unmatched</td></tr>`).join('') : '<tr><td colspan="3">No unmatched POS codes found in the latest import.</td></tr>';
  });
  renderCatalog();
